pub fn nextInLoop(self: *SocketGroup) ?*SocketGroup {
            return us_socket_group_next(self);
    }
};

pub const OnOpenFn = *const fn (*us_socket_t, i32, [*c]u8, i32) callconv(.c) ?*us_socket_t;
pub const OptOnOpenFn = ?OnOpenFn;
pub const OnDataFn = *const fn (*us_socket_t, [*c]u8, i32) callconv(.c) ?*us_socket_t;
pub const OptOnDataFn = ?OnDataFn;
pub const OnFdFn = *const fn (*us_socket_t, i32) callconv(.c) ?*us_socket_t;
pub const OptOnFdFn = ?OnFdFn;
pub const OnSockFn = *const fn (*us_socket_t) callconv(.c) ?*us_socket_t;
pub const OptOnSockFn = ?OnSockFn;
pub const OnCloseFn = *const fn (*us_socket_t, i32, ?*anyopaque) callconv(.c) ?*us_socket_t;
pub const OptOnCloseFn = ?OnCloseFn;
pub const OnConnectingErrFn = *const fn (*ConnectingSocket, i32) callconv(.c) ?*ConnectingSocket;
pub const OptOnConnectingErrFn = ?OnConnectingErrFn;
pub const OnHandshakeFn = *const fn (*us_socket_t, i32, bun.uws.us_bun_verify_error_t, ?*anyopaque) callconv(.c) void;
pub const OptOnHandshakeFn = ?OnHandshakeFn;
pub const ConnectResult = union(enum) {
    socket: *us_socket_t,
    connecting: *ConnectingSocket,
    failed: void,
};

